#!/usr/bin/env python3
"""sen0414_lineage_exam_queue2 v1_0_0 - names the commit of the Mission stage output of the queued lineage 3 (the commit that carried it, as the earlier closures did) and records the ranking and the change item CI-5 that follow from the verified gaps of chapters 1 to 8. A NEW file."""
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
src = W.newest(); t = open(src, encoding="utf-8").read(); now = W.now()[:19]
i = t.index("ex:Out3_Mission a backlog:StageOutput"); j = t.index('backlog:closedAtCommit "PENDING"', i)
t = t[:j] + 'backlog:closedAtCommit "40461de"' + t[j + len('backlog:closedAtCommit "PENDING"'):]
n = ("CHANGE ITEM CI-5 and RANKING (%s UTC), from the verified gaps of chapters 1 to 8 recorded in the mission of ex:Lineage3 (the queued midterm lineage): chapter work comes first. CI-5 (chapter work in this lineage, no exam work): (a) the controller measures the pages of chapters 1 to 8 against the leak probe v1_3_0 and the current page test (not measured so far); (b) the research sets of chapters 7 and 8 get the retrofit already done for chapters 10 to 15: a research task with the first page ABox and its verify task each, planned through a change request in this lineage when the chapter 17 page control is recorded. The ranking of the open items: 1 the chapter 17 page repair control, 2 CI-5, 3 the chapter 16 research, 4 the chapter 17 research, 5 the decks of chapters 19 to 25, then CI-1 and CI-3, the Cross.B pilot and the closing review. THE EARLIEST START OF THE EXAM LINEAGE without cancelling this lineage: the one-lineage rule keeps ex:Lineage3 queued while ex:Lineage2 is InProgress, and Lineage2 will not reach a closing point before the decks of chapters 19 to 25 are done, which is later than the midterm. So the earliest start needs the Owner's single urgency suspension of this lineage (the exam's date is the urgency): it can be asked for when CI-5 is closed (about 3 agent-hours after the chapter 17 control, an estimate nobody has witnessed), because nothing of chapters 10 to 25 is needed by an exam on chapters 1 to 8, and the suspension pauses the chapter work without damaging it. Without that suspension the exam lineage starts after Lineage2 closes. Nothing of the exam is started." % now)
t += "\nex:Lineage3 backlog:hasAuditNote %s .\nex:Lineage2 backlog:hasAuditNote %s .\n" % (W.lit(n), W.lit(n))
print(os.path.basename(W.write_new(src, t, "Mission stage output of lineage 3 names its commit; change item CI-5 and the ranking of the open items with the earliest start of the exam lineage")))
